/* ------------------------------ Difficulty ----------------------------- */
const DIFF = {
  beginner: { label: "Anfänger", color: "#10B981" },
  intermediate: { label: "Mittel", color: "#4F8EF7" },
  advanced: { label: "Fortgeschritten", color: "#F59E0B" },
  expert: { label: "Experte", color: "#7C3AED" },
};
const XP_BY_LEVEL = { beginner: 50, intermediate: 75, advanced: 100, expert: 125 };

/* ------------------------------ Courses -------------------------------- */
// Helper: baut Module/Lektionen mit IDs wie  courseId_<modulnr>_<lektionnr>
function buildCourse(id, name, icon, color, description, mods) {
  let total = 0;
  // Die Erweiterungsmodule gehören zum selben Kurs und hängen sich hinten an.
  // Ein Titel, den es im Kurs schon gibt, wird dabei übersprungen — sonst
  // stünde dasselbe Thema zweimal im Lehrplan.
  const seen = new Set();
  const allMods = [...mods, ...(COURSE_EXTENSIONS[id] || [])]
    .map((m) => ({
      ...m,
      lessons: m.lessons.filter((title) => {
        const key = String(title).toLowerCase().replace(/[^a-z0-9äöüß]+/g, "");
        if (seen.has(key)) return false;
        seen.add(key);
        return true;
      }),
    }))
    .filter((m) => m.lessons.length > 0);

  // Rund 200 Lektionen in 20 Modulen bedeutet etwa zehn je Modul. Kleine
  // Erweiterungsmodule werden deshalb mit dem nächsten gleichen Niveaus
  // zusammengelegt, bis die Zahl stimmt. Die ursprünglichen Einstiegsmodule
  // bleiben unangetastet — an ihren Positionen hängen die Lektions-IDs und
  // damit die handgeschriebenen Inhalte.
  const MAX_MODULES = 20;
  const MERGE_LIMIT = 20;
  const LEVEL_ORDER = ["beginner", "intermediate", "advanced", "expert"];
  const fixed = allMods.slice(0, mods.length);
  const rest = allMods.slice(mods.length);
  while (fixed.length + rest.length > MAX_MODULES) {
    // Zuerst Nachbarn desselben Niveaus, sonst irgendein Nachbarpaar —
    // immer das kleinste, damit große Module nicht noch größer werden.
    let bestAt = -1;
    let bestSize = Infinity;
    let bestSameLevel = false;
    for (let i = 0; i + 1 < rest.length; i++) {
      const size = rest[i].lessons.length + rest[i + 1].lessons.length;
      if (size > MERGE_LIMIT) continue;
      const sameLevel = rest[i].level === rest[i + 1].level;
      if (bestSameLevel && !sameLevel) continue;
      if (sameLevel && !bestSameLevel) { bestAt = i; bestSize = size; bestSameLevel = true; continue; }
      if (size < bestSize) { bestAt = i; bestSize = size; bestSameLevel = sameLevel; }
    }
    if (bestAt < 0) break;                       // nichts mehr sinnvoll zusammenlegbar
    const a = rest[bestAt];
    const b = rest[bestAt + 1];
    const level = LEVEL_ORDER.indexOf(b.level) > LEVEL_ORDER.indexOf(a.level) ? b.level : a.level;
    rest.splice(bestAt, 2, {
      title: `${a.title} & ${b.title}`,
      level,
      lessons: [...a.lessons, ...b.lessons],
    });
  }
  const merged = [...fixed, ...rest];

  const modules = merged.map((m, mi) => {
    const lessons = m.lessons.map((title, li) => {
      total++;
      return {
        id: `${id}_${mi + 1}_${li + 1}`,
        title,
        level: m.level,
        xpReward: XP_BY_LEVEL[m.level],
      };
    });
    return { id: `${id}_m${mi + 1}`, title: m.title, level: m.level, lessons };
  });

  /* Der Lehrplan soll ansteigen. Vorher stand in jedem Kurs Modul 1 auf
     leicht, Modul 3 auf schwer — und Modul 5 wieder auf leicht, weil die
     Erweiterungsmodule hinten angehängt wurden und dort von vorne anfingen.

     Sortiert wird ERST NACH der Vergabe der Kennungen. Die hängen an der
     ursprünglichen Position, und daran wiederum hängen die handgeschriebenen
     Inhalte und der Fortschritt aller Lernenden. Es ändert sich also nur die
     Reihenfolge in der Anzeige, keine einzige Kennung.

     Die Sortierung ist stabil: Module derselben Stufe behalten ihre bisherige
     Reihenfolge, die Einstiegsmodule bleiben damit vorn. */
  const RANG = { beginner: 0, intermediate: 1, advanced: 2, expert: 3 };
  modules.sort((a, b) => (RANG[a.level] ?? 9) - (RANG[b.level] ?? 9));

  return { id, name, icon, color, description, modules, totalLessons: total };
}

